using System;using System.Data;using System.Data.SqlClient;
namespace Training.Manager{public partial class Profile:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();protected void Page_Load(object s,EventArgs e){if(Session["ManagerID"]==null){Response.Redirect("~/Default.aspx");return;}if(!IsPostBack)LoadProfile();}private void LoadProfile(){DataTable d=obj.GetDataTable("SELECT TOP 1 ManagerID,EmpID,EmpName,DOB,DOJ,MobileNo,EmailID,Designation FROM ManagerMaster WHERE ManagerID=@ManagerID AND ISNULL(ActiveStatus,'Y')='Y'",new SqlParameter[]{new SqlParameter("@ManagerID",Session["ManagerID"].ToString())});if(d.Rows.Count==0)return;DataRow r=d.Rows[0];lblManagerID.Text=r["ManagerID"].ToString();lblEmpID.Text=r["EmpID"].ToString();lblName.Text=r["EmpName"].ToString();lblDOB.Text=r["DOB"].ToString();lblDOJ.Text=r["DOJ"].ToString();lblMobile.Text=r["MobileNo"].ToString();lblEmail.Text=r["EmailID"].ToString();lblDesignation.Text=r["Designation"].ToString();}}}